fn swap_first_and_last(a: &Vec<i32>) -> Vec<i32> {
    let n = a.len();

    // Since input length is strictly greater than zero, we can safely unwrap first and last elements.
    if n == 1 {
        // If only one element, return a clone as is.
        return a.clone();
    }

    // Create a new vector with the same length and capacity.
    let mut result = a.clone();

    // Swap the first and last elements.
    result[0] = a[n - 1];
    result[n - 1] = a[0];

    // The interior elements remain unchanged (already cloned).

    result
}